import { Node, mergeAttributes, InputRule } from '@tiptap/core';
import { ReactNodeViewRenderer, NodeViewWrapper, NodeViewContent } from '@tiptap/react';
import React from 'react';
import mermaid from 'mermaid';

// Mermaid Diagram Component that shows the diagram with code visible below
const MermaidDiagramComponent = ({ node, updateAttributes, extension }: any) => {
  const [svg, setSvg] = React.useState('');
  const [error, setError] = React.useState<string | null>(null);
  const containerRef = React.useRef<HTMLDivElement>(null);

  const code = node.attrs.code || '';

  // Clean the code to remove any markdown formatting
  const cleanCode = code.replace(/^```mermaid\s*/, '').replace(/\s*```$/, '').trim();

  const renderDiagram = React.useCallback(async () => {
    if (!cleanCode.trim()) {
      setSvg('');
      setError(null);
      return;
    }

    try {
      // Generate unique ID for this diagram
      const id = `mermaid-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`;
      
      // Configure mermaid for this render
      mermaid.initialize({ 
        startOnLoad: false,
        theme: 'default',
        securityLevel: 'loose',
      });

      const { svg } = await mermaid.render(id, cleanCode);
      setSvg(svg);
      setError(null);
    } catch (err: any) {
      console.warn('Mermaid render error:', err);
      setError(err.message || 'Invalid mermaid syntax');
      setSvg('');
    }
  }, [cleanCode]);

  React.useEffect(() => {
    renderDiagram();
  }, [renderDiagram]);

  const handleCodeChange = (e: React.ChangeEvent<HTMLTextAreaElement>) => {
    updateAttributes({ code: e.target.value });
  };

  return (
    <NodeViewWrapper 
      tag="mermaid-diagram"
      className="mermaid-diagram-wrapper"
      data-mermaid-code={encodeURIComponent(cleanCode)}
      data-code={encodeURIComponent(cleanCode)}
    >
      <div 
        ref={containerRef}
        className="mermaid-diagram-container"
        title="Modifier le code Mermaid ci-dessous"
        style={{ cursor: 'text' }}
      >
        {error ? (
          <div className="mermaid-error">
            <div className="mermaid-error-icon">⚠️</div>
            <div className="mermaid-error-text">Erreur de syntaxe</div>
            <div className="mermaid-error-hint">Corrigez le code ci-dessous</div>
          </div>
        ) : svg ? (
          <div className="mermaid-content">
            <div 
              className="mermaid-svg-container"
              dangerouslySetInnerHTML={{ __html: svg }}
            />
            {/* Show markdown code below the diagram */}
            <div className="mermaid-code-label">
              <pre className="mermaid-code-text">```mermaid
{cleanCode}
```</pre>
            </div>
          </div>
        ) : (
          <div className="mermaid-placeholder">
            <div className="mermaid-placeholder-icon">⇄</div>
            <div className="mermaid-placeholder-text">Diagramme Mermaid</div>
            <div className="mermaid-placeholder-hint">Ajoutez du code ci-dessous</div>
          </div>
        )}
      </div>
      
      {/* Inline code editor */}
      <div className="mermaid-inline-editor">
        <textarea
          className="mermaid-inline-textarea"
          value={code}
          onChange={handleCodeChange}
          placeholder="Entrez votre code Mermaid ici..."
          spellCheck={false}
        />
      </div>
    </NodeViewWrapper>
  );
};

// Custom Tiptap Node Extension
export const MermaidNode = Node.create({
  name: 'mermaidDiagram',
  group: 'block',
  atom: true,
  
  addAttributes() {
    return {
      code: {
        default: '',
      },
    };
  },

  addPasteRules() {
    return [
      {
        find: /```mermaid\s*[\r\n]+([\s\S]*?)[\r\n]*```/g,
        handler: ({ match, range, chain }) => {
          const code = match[1] || '';
          // Clean up the code - remove leading/trailing whitespace from each line
          const cleanedCode = code
            .split(/[\r\n]+/)
            .map(line => line.trim())
            .join('\n')
            .trim();
          
          console.log('Mermaid paste rule triggered:', { code: cleanedCode.substring(0, 50) });
          return chain().deleteRange(range).insertContent(this.type.create({ code: cleanedCode })).run();
        },
      },
      // Also handle inline mermaid blocks without newlines
      {
        find: /```mermaid\s+([^\n]+)```/g,
        handler: ({ match, range, chain }) => {
          const code = match[1] || '';
          console.log('Mermaid paste rule (inline) triggered:', { code });
          return chain().deleteRange(range).insertContent(this.type.create({ code })).run();
        },
      },
    ];
  },

  addCommands() {
    return {
      insertMermaid: (code: string = '') => ({ commands }) => {
        return commands.insertContent({
          type: this.name,
          attrs: { code },
        });
      },
      convertToMermaid: () => ({ state, dispatch }) => {
        const { selection } = state;
        const text = state.doc.textBetween(selection.from, selection.to);
        
        // Check if selected text is a mermaid code block
        const mermaidMatch = text.match(/^```mermaid\n([\s\S]*?)\n```$/);
        if (mermaidMatch) {
          const code = mermaidMatch[1];
          dispatch(state.tr.replaceSelectionWith(this.type.create({ code })));
          return true;
        }
        
        return false;
      },
    };
  },

  parseHTML() {
    return [
      {
        tag: 'mermaid-diagram',
      },
      {
        tag: 'pre',
        getAttrs: (node) => {
          if (typeof node === 'string') return false;
          const codeElement = node.querySelector('code');
          if (codeElement && codeElement.classList.contains('language-mermaid')) {
            const rawCode = codeElement.textContent || '';
            // Decode HTML entities
            const textarea = document.createElement('textarea');
            textarea.innerHTML = rawCode;
            const decodedCode = textarea.value;
            // Remove any markdown formatting
            const cleanCode = decodedCode.replace(/^```mermaid\s*/, '').replace(/\s*```$/, '').trim();
            return {
              code: cleanCode,
            };
          }
          return false;
        },
      },
    ];
  },

  renderHTML({ HTMLAttributes }) {
    const cleanCode = (HTMLAttributes.code || '').replace(/^```mermaid\s*/, '').replace(/\s*```$/, '').trim();
    return ['mermaid-diagram', mergeAttributes(HTMLAttributes, {
      'code': cleanCode,
      'data-code': encodeURIComponent(cleanCode),
    })];
  },

  toHTML(node) {
    const cleanCode = (node.attrs.code || '').replace(/^```mermaid\s*/, '').replace(/\s*```$/, '').trim();
    return ['mermaid-diagram', {
      'code': cleanCode,
      'data-code': encodeURIComponent(cleanCode),
    }];
  },

  addNodeView() {
    return ReactNodeViewRenderer(MermaidDiagramComponent);
  },
});

// Helper function to insert mermaid diagram
export const insertMermaidDiagram = (editor: Editor, code: string = '') => {
  editor.chain().focus().insertContent({
    type: 'mermaidDiagram',
    attrs: { code },
  }).run();
};